import{_ as r,S as d,n as u,p as c,q as t,J as a,C as n,A as s,a2 as l}from"./framework-c4fdf794.js";const m={},h={class:"table-of-contents"},p={class:"notranslate"},v={class:"notranslate"},g={class:"warning custom-block"},b={class:"notranslate"};function f(q,e){const i=d("router-link"),o=d("RouterLink");return u(),c("div",null,[e[32]||(e[32]=t("h1",{id:"under-attack-mode-uam",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#under-attack-mode-uam","aria-hidden":"true"},"#"),a(" Under Attack Mode (UAM)")],-1)),t("nav",h,[t("ul",null,[t("li",null,[n(i,{to:"#overview"},{default:s(()=>[...e[0]||(e[0]=[a("Overview",-1)])]),_:1})]),t("li",null,[n(i,{to:"#how-it-works"},{default:s(()=>[...e[1]||(e[1]=[a("How it works",-1)])]),_:1})]),t("li",null,[n(i,{to:"#prerequisites"},{default:s(()=>[...e[2]||(e[2]=[a("Prerequisites",-1)])]),_:1})]),t("li",null,[n(i,{to:"#enabling-and-disabling-uam"},{default:s(()=>[...e[3]||(e[3]=[a("Enabling and disabling UAM",-1)])]),_:1})]),t("li",null,[n(i,{to:"#managing-rules"},{default:s(()=>[...e[4]||(e[4]=[a("Managing rules",-1)])]),_:1})]),t("li",null,[n(i,{to:"#path-scoping"},{default:s(()=>[...e[5]||(e[5]=[a("Path scoping",-1)])]),_:1})]),t("li",null,[n(i,{to:"#testing-which-rule-matches-a-url"},{default:s(()=>[...e[6]||(e[6]=[a("Testing which rule matches a URL",-1)])]),_:1})]),t("li",null,[n(i,{to:"#monitoring-challenges"},{default:s(()=>[...e[7]||(e[7]=[a("Monitoring challenges",-1)])]),_:1})])])]),e[33]||(e[33]=l('<h2 id="overview" tabindex="-1"><a class="header-anchor" href="#overview" aria-hidden="true">#</a> Overview</h2><p><strong>Under Attack Mode (UAM)</strong> is a WebShield feature that lets a server administrator put one or more <strong>domains</strong> (optionally scoped to specific URL paths) &quot;under attack&quot;. While a domain is under attack, every matching HTTP request is first served a lightweight <strong>JavaScript splash challenge</strong> instead of being passed straight to the site:</p><ul><li>Regular browsers solve the challenge transparently and receive a clearance cookie (its lifetime is configurable per rule); subsequent requests carrying a valid cookie flow through normally.</li><li>Simple bots that cannot run the challenge never reach the application.</li></ul><p>UAM is distinct from the per-IP GreyList / Anti-bot Challenge: UAM decisions are keyed on the request&#39;s <code>(domain, path)</code> and are configured explicitly, rather than being driven by the state of an IP list.</p>',4)),t("p",null,[e[10]||(e[10]=a("The server administrator turns the feature on and manages rules for any domain. If the administrator also allows it, site owners can manage rules for their own domains. Rules are managed either from the control panel — see ",-1)),t("span",p,[n(o,{to:"/dashboard/#under-attack-mode"},{default:s(()=>[...e[8]||(e[8]=[a("WebShield",-1)])]),_:1})]),e[11]||(e[11]=a(" for the administrator interface and ",-1)),t("span",v,[n(o,{to:"/user_interface/#under-attack-mode"},{default:s(()=>[...e[9]||(e[9]=[a("WebShield",-1)])]),_:1})]),e[12]||(e[12]=a(" for the end user one — or with the ",-1)),e[13]||(e[13]=t("span",{class:"notranslate"},[t("code",null,"imunify360-wsctl uam")],-1)),e[14]||(e[14]=a(" commands described below.",-1))]),e[34]||(e[34]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"When to use it"),t("p",null,[a("Turn UAM on for a specific domain when it is the target of an automated flood (for example scripted checkout or login abuse during a sale) and you want to gate "),t("strong",null,"all"),a(" visitors of that domain behind a challenge, regardless of their IP reputation.")])],-1)),t("div",g,[e[22]||(e[22]=t("p",{class:"custom-block-title"},"Availability depends on the environment",-1)),t("p",null,[e[16]||(e[16]=a("UAM is not available on every environment WebShield supports. Before relying on it, check whether the current server supports UAM by running ",-1)),e[17]||(e[17]=t("span",{class:"notranslate"},[t("code",null,"imunify360-wsctl filters")],-1)),e[18]||(e[18]=a(" and confirming the ",-1)),e[19]||(e[19]=t("span",{class:"notranslate"},[t("code",null,"uam")],-1)),e[20]||(e[20]=a(" filter is listed as available — see ",-1)),n(o,{to:"/command_line_interface/#webshield-feature-availability"},{default:s(()=>[...e[15]||(e[15]=[a("WebShield feature availability",-1)])]),_:1}),e[21]||(e[21]=a(". Where UAM is unavailable, only the GreyList / Anti-bot Challenge applies.",-1))])]),e[35]||(e[35]=t("div",{class:"warning custom-block"},[t("p",{class:"custom-block-title"},"Compatibility: Supported Setup"),t("p",null,"cPanel + Apache or Nginx (module loaded) only.")],-1)),e[36]||(e[36]=t("h2",{id:"how-it-works",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#how-it-works","aria-hidden":"true"},"#"),a(" How it works")],-1)),t("ul",null,[e[30]||(e[30]=l("<li>A domain is placed under attack by creating a <strong>UAM rule</strong>. A rule pairs a <code>domain</code> (optionally narrowed to a path-set) with the clearance-cookie lifetime to grant once a visitor solves the challenge.</li><li>When a request matches an <strong>active</strong> rule, WebShield returns the JS splash challenge and does not forward the request to the backend until the visitor passes.</li><li>UAM is <strong>fail-open</strong>: if the feature is disabled, the request has no <code>Host</code>, the rule store cannot be read, or no active rule matches, the request simply proceeds through the normal WebShield flow. UAM never blocks a request outright — it only inserts a challenge.</li>",3)),t("li",null,[e[24]||(e[24]=a("Whitelisted IP addresses are ",-1)),e[25]||(e[25]=t("strong",null,"never",-1)),e[26]||(e[26]=a(" challenged: the whitelist is consulted before the application-level checks, so an IP on the ",-1)),t("span",b,[n(o,{to:"/command_line_interface/#whitelist"},{default:s(()=>[...e[23]||(e[23]=[a("White List",-1)])]),_:1})]),e[27]||(e[27]=a(" reaches the site directly. Whitelist any legitimate automation that cannot solve a JavaScript challenge — search-engine crawlers, monitoring, server-side integrations, or ",-1)),e[28]||(e[28]=t("span",{class:"notranslate"},[t("code",null,"wp-cron")],-1)),e[29]||(e[29]=a(" invoked over HTTP.",-1))]),e[31]||(e[31]=t("li",null,[a("The feature is gated behind a single on/off toggle that is "),t("strong",null,"off by default"),a(", and all UAM state is stored on the server itself.")],-1))]),e[37]||(e[37]=l(`<h2 id="prerequisites" tabindex="-1"><a class="header-anchor" href="#prerequisites" aria-hidden="true">#</a> Prerequisites</h2><ul><li>WebShield version &gt;= 1.45.0 installed and running in an environment where UAM is available (see the note above). The core rule commands and the service toggle have been available since 1.44.2; the per-rule challenge-cookie lifetime and the <span class="notranslate"><code>uam test</code></span> command described below were added in 1.45.0.</li><li>Root access to the server. The <span class="notranslate"><code>imunify360-wsctl uam</code></span> command described below must be run as <code>root</code>. Site owners manage their own rules from the control panel instead.</li></ul><h2 id="enabling-and-disabling-uam" tabindex="-1"><a class="header-anchor" href="#enabling-and-disabling-uam" aria-hidden="true">#</a> Enabling and disabling UAM</h2><p>UAM is <strong>off by default</strong>. Enable the feature before creating rules — while it is disabled, all rule and counter commands fail with a <code>service_disabled</code> error.</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl uam settings service            # show the current {enabled} state
imunify360-wsctl uam settings service enable      # turn UAM on, server-wide
imunify360-wsctl uam settings service disable     # turn UAM off
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><p>Disabling the feature stops all challenges immediately; your rules are preserved and take effect again when you re-enable it.</p><p>A second, independent switch controls whether site owners may manage rules for their own domains in the control panel. It is off by default, so UAM starts out administrator-only:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl uam settings visibility            # show the current {allowed_for_users} state
imunify360-wsctl uam settings visibility enable     # let site owners manage their own rules
imunify360-wsctl uam settings visibility disable    # administrator-only again
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p><span class="notranslate"><code>Enable WebShield</code></span> in <span class="notranslate">Settings</span> does not control UAM. It turns off the GreyList and the Anti-bot Challenge; UAM keeps its own on/off state.</p></div><h2 id="managing-rules" tabindex="-1"><a class="header-anchor" href="#managing-rules" aria-hidden="true">#</a> Managing rules</h2><p>A rule is created from a small JSON payload. The fields are:</p><table><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><span class="notranslate"><code>domain</code></span></td><td>yes</td><td>Hostname to put under attack (up to 253 characters). A leading wildcard is accepted: <span class="notranslate"><code>*.example.com</code></span> matches the subdomains of <span class="notranslate"><code>example.com</code></span> but not <span class="notranslate"><code>example.com</code></span> itself, while <span class="notranslate"><code>.example.com</code></span> matches both. Hostnames are compared verbatim, so write the domain in lower case.</td></tr><tr><td><span class="notranslate"><code>cookie_ttl</code></span></td><td>yes</td><td>How long a visitor&#39;s clearance cookie stays valid after they solve the challenge, before they are challenged again. A Go-style duration string using the units <span class="notranslate"><code>s</code></span>, <span class="notranslate"><code>m</code></span>, <span class="notranslate"><code>h</code></span> (compound values such as <span class="notranslate"><code>1h30m</code></span> are allowed), between <strong>10 seconds and 3 days</strong>.</td></tr><tr><td><span class="notranslate"><code>label</code></span></td><td>no</td><td>Free-text note (up to 128 characters).</td></tr><tr><td><span class="notranslate"><code>paths</code></span></td><td>no</td><td>Path-scoping block (see <a href="#path-scoping">Path scoping</a> below). Omit it to cover the whole domain.</td></tr></tbody></table><p>A new rule is active as soon as it is created.</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># Put a whole domain under attack; re-challenge visitors after 1 hour:
imunify360-wsctl uam add &#39;{&quot;domain&quot;:&quot;shop.example.com&quot;,&quot;cookie_ttl&quot;:&quot;1h&quot;,&quot;label&quot;:&quot;Black Friday&quot;}&#39;

# Scope the rule to specific paths (see &quot;Path scoping&quot; below):
imunify360-wsctl uam add &#39;{&quot;domain&quot;:&quot;shop.example.com&quot;,&quot;cookie_ttl&quot;:&quot;30m&quot;,&quot;paths&quot;:{&quot;mode&quot;:&quot;include&quot;,&quot;matchers&quot;:[{&quot;value&quot;:&quot;/checkout&quot;,&quot;condition&quot;:&quot;prefix&quot;}]}}&#39;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><p>List the current rules (a table by default, <code>--json</code> for raw output, <code>--domain</code> and <code>--owner</code> to filter by exact domain or by rule owner):</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl uam list
imunify360-wsctl uam list --domain shop.example.com --json
imunify360-wsctl uam list --owner alice
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><p>The table shows <code>ID OWNER ACTIVE DOMAIN COOKIE_TTL LABEL</code>. The <code>ID</code> is a positive integer assigned by WebShield when the rule is created; you use it to edit or delete the rule. <code>OWNER</code> is <code>admin</code> for rules created by the server administrator, or the user name for a rule a site owner created for their own domain.</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl uam list
ID  OWNER  ACTIVE  DOMAIN            COOKIE_TTL  LABEL
7   admin  true    shop.example.com  1h          Black Friday
8   alice  true    blog.example.com  30m         Comment spam
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><p>Edit a rule with a partial JSON payload — only <code>active</code>, <code>cookie_ttl</code>, <code>label</code>, and <code>paths</code> can be changed. Temporarily pausing a rule is done by setting <code>active</code> to <code>false</code>:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl uam edit 7 &#39;{&quot;active&quot;:false}&#39;       # pause the rule (keep it for later)
imunify360-wsctl uam edit 7 &#39;{&quot;cookie_ttl&quot;:&quot;2h&quot;}&#39;    # change the clearance-cookie lifetime
imunify360-wsctl uam edit 7 &#39;{&quot;label&quot;:&quot;BF sale&quot;}&#39;    # rename
imunify360-wsctl uam edit 7 &#39;{&quot;paths&quot;:null}&#39;         # clear paths -&gt; back to whole-domain
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><p>Delete a rule by ID. Delete is idempotent — deleting an ID that no longer exists still succeeds:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl uam delete 7
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></div><h2 id="path-scoping" tabindex="-1"><a class="header-anchor" href="#path-scoping" aria-hidden="true">#</a> Path scoping</h2><p>By default a rule covers the whole domain. Add a <code>paths</code> block to challenge only some URLs. The block has a <code>mode</code> and a list of <code>matchers</code>:</p><ul><li><code>mode: &quot;include&quot;</code> — the matchers list the paths that <strong>are</strong> under attack. A request is challenged only if it matches one of them.</li><li><code>mode: &quot;exclude&quot;</code> — the matchers list <strong>exceptions</strong>. A matching request is let through; everything else on the domain is challenged.</li></ul><p>Each matcher is <code>{&quot;value&quot;: &quot;...&quot;, &quot;condition&quot;: &quot;...&quot;}</code>. A rule may hold between 1 and 32 matchers, and a request matches the block if it satisfies <strong>any</strong> of them. The available conditions are:</p><table><thead><tr><th>Condition</th><th>Matches when the request URI</th></tr></thead><tbody><tr><td><span class="notranslate"><code>equals</code></span></td><td>is exactly the value</td></tr><tr><td><span class="notranslate"><code>prefix</code></span></td><td>begins with the value</td></tr><tr><td><span class="notranslate"><code>suffix</code></span></td><td>ends with the value</td></tr><tr><td><span class="notranslate"><code>contains</code></span></td><td>contains the value anywhere</td></tr><tr><td><span class="notranslate"><code>wildcard</code></span></td><td>matches the value as a wildcard pattern, where <span class="notranslate"><code>*</code></span> stands for any number of characters, including <span class="notranslate"><code>/</code></span></td></tr><tr><td><span class="notranslate"><code>query_contains</code></span></td><td>has a query string containing the value</td></tr><tr><td><span class="notranslate"><code>query_regex</code></span></td><td>has a query string matching the value as a regular expression</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">The query string is part of what is matched</p><p>Matchers are applied to the whole request URI, query string included. An <span class="notranslate"><code>equals</code></span> matcher for <span class="notranslate"><code>/wp-login.php</code></span> therefore does <strong>not</strong> match <span class="notranslate"><code>/wp-login.php?redirect_to=/wp-admin/</code></span> — use <span class="notranslate"><code>prefix</code></span> when the URL may carry a query string. Matching is case-sensitive. Verify the result with <span class="notranslate"><a href="#testing-which-rule-matches-a-url"><code>uam test</code></a></span>.</p></div><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># Only challenge /api and everything under /checkout:
imunify360-wsctl uam add &#39;{&quot;domain&quot;:&quot;shop.example.com&quot;,&quot;paths&quot;:{&quot;mode&quot;:&quot;include&quot;,&quot;matchers&quot;:[{&quot;value&quot;:&quot;/api&quot;,&quot;condition&quot;:&quot;equals&quot;},{&quot;value&quot;:&quot;/checkout&quot;,&quot;condition&quot;:&quot;prefix&quot;}]}}&#39;

# Challenge the whole domain EXCEPT the health-check endpoint:
imunify360-wsctl uam add &#39;{&quot;domain&quot;:&quot;shop.example.com&quot;,&quot;paths&quot;:{&quot;mode&quot;:&quot;exclude&quot;,&quot;matchers&quot;:[{&quot;value&quot;:&quot;/healthz&quot;,&quot;condition&quot;:&quot;equals&quot;}]}}&#39;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><h2 id="testing-which-rule-matches-a-url" tabindex="-1"><a class="header-anchor" href="#testing-which-rule-matches-a-url" aria-hidden="true">#</a> Testing which rule matches a URL</h2><p><span class="notranslate"><code>uam test</code></span> checks whether a given URL would be challenged, using the <strong>exact same matching as live traffic</strong>. It is the quickest way to verify a rule&#39;s path scoping without generating real requests.</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl uam test example.com/path          # scheme optional; host required
imunify360-wsctl uam test https://shop.example.com/api?x=1
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div></div><p>The scheme is optional, the host is required, and both the path and the query string are significant (only a trailing <code>#fragment</code> is ignored, and an empty path is treated as <code>/</code>). When a rule matches, the command prints that rule as JSON; otherwise it prints <span class="notranslate"><code>No matching rule</code></span>:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl uam test shop.example.com/checkout
[
  {
    &quot;id&quot;: 7,
    &quot;owner&quot;: &quot;admin&quot;,
    &quot;active&quot;: true,
    &quot;label&quot;: &quot;Black Friday&quot;,
    &quot;domain&quot;: &quot;shop.example.com&quot;,
    &quot;cookie_ttl&quot;: &quot;1h&quot;,
    &quot;paths&quot;: {
      &quot;mode&quot;: &quot;include&quot;,
      &quot;matchers&quot;: [
        {
          &quot;value&quot;: &quot;/checkout&quot;,
          &quot;condition&quot;: &quot;prefix&quot;
        }
      ]
    }
  }
]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p><span class="notranslate"><code>uam test</code></span> only reports a match while UAM is enabled; if the service is disabled it returns a <span class="notranslate"><code>service_disabled</code></span> error.</p></div><h2 id="monitoring-challenges" tabindex="-1"><a class="header-anchor" href="#monitoring-challenges" aria-hidden="true">#</a> Monitoring challenges</h2><p>Each challenge served for a rule is counted. Use <code>counters</code> to see which rules are actively challenging traffic, busiest first:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl uam counters                       # all rules with hits today, busiest first
imunify360-wsctl uam counters --since 24h           # a rolling window instead of &quot;today&quot;
imunify360-wsctl uam counters shop.example.com      # filter by exact domain
imunify360-wsctl uam counters 7                      # filter by rule id
imunify360-wsctl uam counters --owner alice          # filter by rule owner
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><p>The single optional argument is auto-detected: a positive integer is treated as a rule ID, anything else as an exact domain. The <code>--since</code> window is one of <code>today</code> (default), <code>1h</code>, <code>4h</code>, <code>24h</code>, <code>4d</code>, or <code>7d</code>. Output columns are <code>ID ACTIVE DOMAIN HITS LABEL</code>. Only rules with at least one challenge in the window are listed, and challenge counts are retained for 7 days.</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl uam counters
ID  ACTIVE  DOMAIN            HITS  LABEL
7   true    shop.example.com  1523  Black Friday
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div>`,40))])}const y=r(m,[["render",f],["__file","index.html.vue"]]);export{y as default};
